 import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './Login.css';
import HomeIcon from '../Common/HomeIcon';
import { login } from '../../services/api';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState(null);

  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!email || !password) {
      alert('Completează toate câmpurile!');
      return;
    }

    try {
      const result = await login({ email, password });

      if (result && result.token && result.userId !== undefined && result.userId !== null) {
         localStorage.setItem('token', result.token);
         localStorage.setItem('userId', result.userId);

         if (result.username !== undefined && result.username !== null) {
             localStorage.setItem('username', result.username);
         } else {
             localStorage.setItem('username', email.split('@')[0]);
         }

         if (result.email !== undefined && result.email !== null) {
             localStorage.setItem('email', result.email);
         } else {
             localStorage.setItem('email', email);
         }


         window.dispatchEvent(new Event('authChange'));
         navigate('/', { replace: true });

      } else {
         const errorMessage = result && result.message ? result.message : 'Login failed: Unexpected response from server.';
         setError(errorMessage);
         alert(errorMessage);
      }

    } catch (err) {
      const errorMessage = err.message || 'A apărut o eroare la autentificare.';
      setError(errorMessage);
      alert(errorMessage);
    }
  };

  return (
    <div className="login-container">
      <HomeIcon />
      <h1>Login</h1>

      <form onSubmit={handleSubmit}>
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <input
          type="password"
          placeholder="Parolă"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <button type="submit">Login</button>

        {error && <p style={{ color: 'red' }}>{error}</p>}

        <p style={{ textAlign: 'center', marginTop: '15px' }}>
          Nu ai un cont? <Link to="/register">Înregistrează-te</Link>
        </p>
      </form>
    </div>
  );
}

export default Login;
